\begin{proposition}\label{completeness1}  
The following completeness condition is satisfied: for all $m,n\in\Z$,
$$
\sum_{\epsilon\in\{\pm1\}}f_\epsilon(m)f_\epsilon(n)+\int_0^\pi \sum_{\mu,\epsilon\in\{\pm1\}}f_{x,\mu,\epsilon}(m)f_{x,\mu,\epsilon}(n)\frac{\mathrm{d}x}{H_{\mu\epsilon}(x)}=\delta_{m,n}.
$$
\end{proposition}

\begin{thm}[\cite{MR930082}]
\label{thm:ChIneq}
Let $\sfP$ be a reversible Markov kernel. Then it holds
\begin{equation}
\label{eqn:ChIneq}
    \frac{\kappa}{2} \Phi(\sfP)^2 \le \Gap(\sfP) \le \Phi(\sfP),
\end{equation}
where $\kappa \ge 1$ is a universal constant.
\end{thm}

\begin{thm}\label{thm:poisson_equation_spectral_gap_general}
Let $p \in (1,\infty)$ and $f \in L^p_0(\pi)$. 
If the Markov kernel $K$ admits a spectral gap, then, the space $L^p_0(\pi)$ contains exactly one solution of Poisson's equation $u \in L^p_0(\pi)$ (with forcing function $f$) and we have 
\[
\norm{u}_{L^p(\pi)}
\leq 
\begin{cases}
	\frac{2^{2/p}}{1- \kappa^{2\frac{p-1}{p}}} \norm{f}_{L^p(\pi)} \qquad&\text{ if } p \in (1,2), \\[1.5ex]
	\frac{1}{1-\kappa} \norm{f}_{L^2(\pi)} &\text{ if } p = 2, \\[1.2ex]
	\frac{2^{2\frac{p-1}{p}}}{1-\kappa^{2/p}}\norm{f}_{L^p(\pi)} &\text{ if } p\in (2, \infty),
\end{cases}
\] 
where $\kappa = \norm{K}_{L^2_0(\pi) \to L^2_0(\pi)}< 1$. 
\end{thm}
